def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    """
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    combinations = []
    for i in range(1, 10):
        for j in range(1, 10):
            for k in range(1, 10):
                if i * 2 == j and i * 3 == k:
                    combinations.append((i, j, k))
    return sorted(combinations)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i, c in enumerate(encoded):
        if c not in mapping:
            mapping[c] = original[i]
        elif mapping[c] != original[i]:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for c in message:
        if c in mapping:
            decoded += mapping[c]
        else:
            return "Failed"

    return decoded

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if last == n:
        return 1
    count = 0
    for i in range(n, last):
        if i <= last // 2:
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 % (a * x0) == 0:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            elif math.gcd(a, b) == 1:
                count += 2
    return count

def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    def helper(start, end):
        if start > end:
            return ''
        if start == end:
            return inorder[start]
        root = postorder[postorder_idx[inorder[start]]]
        left = helper(start, inorder_idx[root] - 1)
        right = helper(inorder_idx[root] + 1, end)
        return root + left + right
    return helper(0, len(inorder) - 1)

def find_most_unhappy_day(schedule):
    total_hours = [school + extra for school, extra in schedule]
    max_unhappiness = max(total_hours)
    if max_unhappiness <= 8:
        return 0
    return total_hours.index(max_unhappiness) + 1
